window.STORY_CHAPTERS["c32ef5ac2a5cd5e4f"]={"id":"c32ef5ac2a5cd5e4f","lines":[{"uid":"talk.vc.home_time_dakira_7#originalText","id":"talk.vc.home_time_dakira_7","speaker":{"cn":"达基拉","en":"Dakira","ja":"ダキラ"},"text":{"cn":"您一定累了吧？泡个澡让身体休息一下吧。","en":"You must be tired. Please, warm yourself in the bath.","ja":"さぞお疲れでしょう湯浴みでお体を休めてください"},"kind":"dialogue"},{"uid":"talk.vc.home_time_dakira_10#originalText","id":"talk.vc.home_time_dakira_10","speaker":{"cn":"达基拉","en":"Dakira","ja":"ダキラ"},"text":{"cn":"夜间警备就交给我吧。我不会让任何人靠近您的寝室。","en":"Rest assured, I will guard your room at night. I won't let anyone come near you.","ja":"夜間の警護はお任せください誰もご寝所へは近づけません"},"kind":"dialogue"},{"uid":"talk.vc.home_time_deathgun_1#originalText","id":"talk.vc.home_time_deathgun_1","speaker":{"cn":"死枪","en":"Death Gun","ja":"デス・ガン"},"text":{"cn":"哼、哼、哼。见到、早上的、太阳。这说不定是、最后一次呢。","en":"Heh heh heh. This will probably be the last morning I see.","ja":"ク、ク、ク朝日を、見るのは、これが最後かも、しれない"},"kind":"dialogue"},{"uid":"talk.vc.home_time_deathgun_4#originalText","id":"talk.vc.home_time_deathgun_4","speaker":{"cn":"死枪","en":"Death Gun","ja":"デス・ガン"},"text":{"cn":"外头、明亮、和我、无关。因为、我绝对，无法直视。","en":"Even if it's bright out, it makes no difference for me. I will never be able to see again.","ja":"明るくても、俺には、関係ない決して、目視することはできないの、だから"},"kind":"dialogue"},{"uid":"talk.vc.home_time_deathgun_7#originalText","id":"talk.vc.home_time_deathgun_7","speaker":{"cn":"死枪","en":"Death Gun","ja":"デス・ガン"},"text":{"cn":"哼、哼、哼。今晚、出现、黑色、星星。是一个、很适合、死人的、美好夜晚。","en":"Heh, heh, heh. Tonight we will be able to see the black star. It's a good night for someone to die.","ja":"ク、ク、ク今夜は、黒い星が、出ているな誰かが、死ぬには、いい夜だ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_deathgun_10#originalText","id":"talk.vc.home_time_deathgun_10","speaker":{"cn":"死枪","en":"Death Gun","ja":"デス・ガン"},"text":{"cn":"要、睡、吗？你、明明、有可能、再也、醒不来了。","en":"Would it be alright for me to rest my eyes? Even though I probably won't be able to open them up again.","ja":"眠って、いいのか?二度と、目を、覚まさないかも、しれないのに"},"kind":"dialogue"},{"uid":"talk.vc.home_time_deusolbert_1#originalText","id":"talk.vc.home_time_deusolbert_1","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"世上哪有人会睡得这么晚。","en":"What kind of cad sleeps in this late?","ja":"このような時間まで寝ておるヤツがあるか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_deusolbert_2#originalText","id":"talk.vc.home_time_deusolbert_2","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"今天也必须为了人界的和平，尽心尽力。","en":"Another day of hard work to protect humanity.","ja":"今日も人界の平和のため尽力せねば"},"kind":"dialogue"},{"uid":"talk.vc.home_time_deusolbert_4#originalText","id":"talk.vc.home_time_deusolbert_4","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"还得喂飞龙吃饭才行。","en":"One must also feed one's dragon.","ja":"飛竜にも食事をやらねばな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_deusolbert_5#originalText","id":"talk.vc.home_time_deusolbert_5","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"索鲁斯的力量非常伟大，整个空间都充满着神圣力。","en":"Solus's powers are great. The skies are filled with divine energy.","ja":"ソルスの力は偉大だ空間に神聖力が満ちている"},"kind":"dialogue"},{"uid":"talk.vc.home_time_deusolbert_7#originalText","id":"talk.vc.home_time_deusolbert_7","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"好，我们休息吧。","en":"Well. Let us rest.","ja":"さて、休むとしようか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_deusolbert_8#originalText","id":"talk.vc.home_time_deusolbert_8","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"今天要继续进行任务，暂时是没得休息了。","en":"I must continue with my duties for the rest of the day. There will be little time for rest.","ja":"今日はこのまま任務の続きだしばらくは休めそうにない"},"kind":"dialogue"},{"uid":"talk.vc.home_time_deusolbert_10#originalText","id":"talk.vc.home_time_deusolbert_10","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"怎么了？你也在进行任务吗？夜晚的任务对一般人来说很辛苦吧。","en":"Are you also out on a mission? Night missions must be difficult for ordinary humans.","ja":"どうした、そちらも任務か?夜の任務は、常人には大変だろう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_deusolbert_11#originalText","id":"talk.vc.home_time_deusolbert_11","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"能休息的时候就要休息，那也是武人的职责。","en":"Rest well when you are given the chance. That is a fighter's duty.","ja":"休める時に休んでおけよそれも武人の務めだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_diavel_1#originalText","id":"talk.vc.home_time_diavel_1","speaker":{"cn":"迪亚贝尔","en":"Diavel","ja":"ディアベル"},"text":{"cn":"好了，全新的早晨！今天要去哪里呢？","en":"It's a brand new day! Where shall we go today?","ja":"さあ、新しい朝だ!今日はどこへ行こうか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_diavel_4#originalText","id":"talk.vc.home_time_diavel_4","speaker":{"cn":"迪亚贝尔","en":"Diavel","ja":"ディアベル"},"text":{"cn":"你也要吃饭吗？那我们一起吃吧。","en":"Are you hungry, too? Let's eat together.","ja":"君も食事かい?だったら一緒に食べようか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_diavel_7#originalText","id":"talk.vc.home_time_diavel_7","speaker":{"cn":"迪亚贝尔","en":"Diavel","ja":"ディアベル"},"text":{"cn":"今天也辛苦你了。好好休息，准备迎接明天吧！","en":"Good work today. Make sure you rest up well tonight.","ja":"今日もお疲れさまゆっくり休んで明日に備えようぜ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_diavel_10#originalText","id":"talk.vc.home_time_diavel_10","speaker":{"cn":"迪亚贝尔","en":"Diavel","ja":"ディアベル"},"text":{"cn":"不睡的话明天会很难受喔。对身在最前线的人而言，管理身体状况也是个重要的工作。","en":"If you don't sleep, you'll be off your game tomorrow. Taking care of your physical health is essential for someone who's on the front lines.","ja":"寝ないと明日きついぞ?体調管理も、最前線の人間にとっては大事な仕事だ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_dil_1#originalText","id":"talk.vc.home_time_dil_1","speaker":{"cn":"蒂伊‧艾‧耶尔","en":"Dee Eye Ell","ja":"ディー・アイ・エル"},"text":{"cn":"早安，陛下。暗黑术师的部队已经准备好，可以随时出发。","en":"Good morning, your majesty. The battalion of Dark Sorcerers is ready to depart at a moments notice.","ja":"おはようございます、陛下暗黒術師の部隊、いつでも出陣可能な状態で控えております"},"kind":"dialogue"},{"uid":"talk.vc.home_time_dil_4#originalText","id":"talk.vc.home_time_dil_4","speaker":{"cn":"蒂伊‧艾‧耶尔","en":"Dee Eye Ell","ja":"ディー・アイ・エル"},"text":{"cn":"呵呵，那些猪的性命都消散了。再死更多，为我的术式注入更多的神圣力吧……","en":"Gah! Drive away these pigs! More of them should die so that I don't have to waste my Sacred Arts...","ja":"くくく、豚どもが命を散らしているもっと死んで、術式のための神聖力をため込むのだ……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_dil_7#originalText","id":"talk.vc.home_time_dil_7","speaker":{"cn":"蒂伊‧艾‧耶尔","en":"Dee Eye Ell","ja":"ディー・アイ・エル"},"text":{"cn":"陛下，我可以在您身旁倒酒吗？","en":"Your majesty, may I pour you a drink?","ja":"陛下、お側で酒をお注ぎしてもよろしいですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_dil_10#originalText","id":"talk.vc.home_time_dil_10","speaker":{"cn":"蒂伊‧艾‧耶尔","en":"Dee Eye Ell","ja":"ディー・アイ・エル"},"text":{"cn":"我本来想着要是睡着了可能有机可乘……但是不愧是将军，睡觉的地方守备也特别森严。","en":"I was thinking perhaps when he was asleep... But the general's room surely must be well protected.","ja":"眠っていれば、あるいはと思ったが……さすがは将軍寝所の守りは堅いか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_1#originalText","id":"talk.vc.home_time_edith_1","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"早安。虽然嘴上这么说，但我接下来要睡了。","en":"Good morning... Well, goodnight, technically. I'm about to go to sleep.","ja":"おはようと言っても、あたしはこれから寝るんだけどね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_2#originalText","id":"talk.vc.home_time_edith_2","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"差不多该出发去任务地点了。最后一起吃个饭吧。","en":"I have to return to my post soon. Let's break our fast together before I leave.","ja":"そろそろ任地へ出発だから最後に、一緒にご飯食べましょ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_3#originalText","id":"talk.vc.home_time_edith_3","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"你今天也很早起呢。我也要多少向你看齐才行。","en":"You certainly are up early again today. I should follow your example.","ja":"今日も早起きねあたしも少しは見習わないと"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_4#originalText","id":"talk.vc.home_time_edith_4","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"你在云上庭园啊。这里很让人放松对吧……","en":"So you were in the Cloudtop Garden. I don't blame you. It is so relaxing up here.","ja":"雲上庭園にいたのねここ、落ち着くわよね……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_5#originalText","id":"talk.vc.home_time_edith_5","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我今天有碰到元老长，根本糟透了……我要赶快忘掉。","en":"I ran into the Prime Senator today. Eew. So gross! I need to get that visual out of my mind.","ja":"今日は元老長に会っちゃったもう最悪……早く忘れないと"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_6#originalText","id":"talk.vc.home_time_edith_6","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"偶而回到教会，就会觉得饭菜好吃。","en":"Sometimes I make a trip home to the Church, just to eat the delicious food.","ja":"たまに教会に帰ってくるとご飯がおいしいの"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_7#originalText","id":"talk.vc.home_time_edith_7","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"夜晚是暗之时间，姑且还是要保持点警戒。","en":"Night is the time for Dark agents, so one must always be on guard.","ja":"夜は闇の時間だから一応警戒しておかないとね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_8#originalText","id":"talk.vc.home_time_edith_8","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"今天的工作结束了～要一起洗澡吗？","en":"Work is done for the day! Wanna take a bath with me?","ja":"今日の仕事は終わりーお風呂一緒に入ろっか? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_9#originalText","id":"talk.vc.home_time_edith_9","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我要从这个时间开始，才会发挥本领。","en":"I'm at my best this time of day.","ja":"あたしが本領発揮するのはこの時間からだよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_10#originalText","id":"talk.vc.home_time_edith_10","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"嗯，你还醒着吗？该不会是想我了吧？","en":"Mm, you're still awake? Wait a minute, did you miss me?","ja":"ん、まだ起きてたの? もしかして、あたしに会いたかった?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_11#originalText","id":"talk.vc.home_time_edith_11","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"晚上能看见人的百态。不论是美好的部分，还是肮脏的部分……","en":"The hidden sides to a person's character are often revealed at night. The good, the bad, and the ugly...","ja":"夜は人のいろんな面が見られるよねキレイなところも汚いところも……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_edith_12#originalText","id":"talk.vc.home_time_edith_12","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"你醒啦？不过，还是休息一下比较好，多少能消除一些疲劳。","en":"Did you wake up? But you should still stay in bed. Even lying awake helps rejuvenate you.","ja":"目が覚めちゃったのかでも、休んでたほうがいいよ少しでも疲れがとれるから"},"kind":"dialogue"},{"uid":"talk.vc.home_time_egome_1#originalText","id":"talk.vc.home_time_egome_1","speaker":{"cn":"伊格姆","en":"Egome","ja":"イゴーム"},"text":{"cn":"已经这么晚了……差不多该起床啦。","en":"It's later than I thought. We'd better get up.","ja":"もうこんな時間か……そろそろ起きるか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_egome_4#originalText","id":"talk.vc.home_time_egome_4","speaker":{"cn":"伊格姆","en":"Egome","ja":"イゴーム"},"text":{"cn":"干嘛？我可不会把午餐分给你喔。","en":"What, you want lunch? Well, I'm not sharing mine.","ja":"なんだ、昼飯ならわけてはやらないぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_egome_7#originalText","id":"talk.vc.home_time_egome_7","speaker":{"cn":"伊格姆","en":"Egome","ja":"イゴーム"},"text":{"cn":"差不多是吃晚餐的时间了……有什么东西可以吃吗？","en":"It's almost dinnertime. Anything available?","ja":"そろそろ晩飯の時間だが……何かないのか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_egome_10#originalText","id":"talk.vc.home_time_egome_10","speaker":{"cn":"伊格姆","en":"Egome","ja":"イゴーム"},"text":{"cn":"……你很啰唆耶。明天再说啦。","en":"Oh, shut up. Can't it wait until tomorrow?","ja":"……うるせえなあ明日にしろよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eiji_1#originalText","id":"talk.vc.home_time_eiji_1","speaker":{"cn":"瑛二","en":"Eiji","ja":"エイジ"},"text":{"cn":"早安。一早就听得到你的歌声，醒来的时候很舒服呢。","en":"Morning. Listening to your singing in the morning is a good way to start the day.","ja":"おはよう朝から君の歌を聴けていい目覚めだったよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eiji_4#originalText","id":"talk.vc.home_time_eiji_4","speaker":{"cn":"瑛二","en":"Eiji","ja":"エイジ"},"text":{"cn":"好，我们就出门吧。这个世界为你带来的刺激，想必会变成你的财产吧。","en":"Well, shall we go out somewhere? The excitement of this world is sure to become an asset of yours.","ja":"さて、どこかに出かけようかこの世界の刺激は、きっと君の財産になるだろうから"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eiji_7#originalText","id":"talk.vc.home_time_eiji_7","speaker":{"cn":"瑛二","en":"Eiji","ja":"エイジ"},"text":{"cn":"抱歉，我今天就到这里，先失陪了。我有点累，大概是因为还没习惯吧。","en":"Excuse me, let's call it a day here. Looks like I've gotten a little tired. Guess I am not used to this sensation.","ja":"すまない、今日はこれで失礼する慣れない感覚で、少し疲れてしまったみたいでね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eiji_10#originalText","id":"talk.vc.home_time_eiji_10","speaker":{"cn":"瑛二","en":"Eiji","ja":"エイジ"},"text":{"cn":"怎么了？睡不着吗？那，不用勉强自己去睡，我在旁边醒着陪你吧？","en":"What's up? Can't sleep? No point and trying to sleep. How about staying up with me?","ja":"どうした、眠れないのか?なら、無理に寝なくてもいい一緒に起きていようか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eldrie_1#originalText","id":"talk.vc.home_time_eldrie_1","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"早安。您的容颜今日也同样动人呢。","en":"Good morning. You look lovely today, as always.","ja":"おはようございます今日もお美しゅうございますな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eldrie_2#originalText","id":"talk.vc.home_time_eldrie_2","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"鸟鸣嘤嘤催人醒，说来也是别有风情呢。","en":"Awakening to the songs of the birds is a truly beautiful thing.","ja":"鳥のさえずりで目を覚ますというのも乙なものです"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eldrie_4#originalText","id":"talk.vc.home_time_eldrie_4","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"本日的餐点没什么过失呢。虽说也难以称得上完美。","en":"Today's meal was passable. Difficult to call perfect.","ja":"今日の食事はまあまあでしたね無論、完璧とは言い難くはありましたが"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eldrie_5#originalText","id":"talk.vc.home_time_eldrie_5","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"今天天气很好，适合乘着泷刳飞翔。您要不要同行呢？","en":"The perfect day for a ride on a dragon. Would you like to join me?","ja":"滝刳で飛ぶにはいい日ですねいかがですか、ご一緒に"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eldrie_7#originalText","id":"talk.vc.home_time_eldrie_7","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"虽非什么稀世美酒，但有瓶陈了百年的红酒，还请您移驾。","en":"It's nothing much, but it is a 100-year-old red. Have some, if you'd like.","ja":"大したものはありませぬが100年ものの赤がございますゆえそちらをどうぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eldrie_8#originalText","id":"talk.vc.home_time_eldrie_8","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"夜露珠珠轻濡花，这也是别有趣味呢。","en":"The flowers, moist with the dewy night air, are quite charming.","ja":"夜露に濡れる花もまた趣のあるものでございますな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eldrie_10#originalText","id":"talk.vc.home_time_eldrie_10","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"您睡不着吗？那么请用这杯热牛奶吧。","en":"Having trouble sleeping? Then please, have a milk.","ja":"眠れないのですか?では、こちらをどうぞ温めたミルクです"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eldrie_11#originalText","id":"talk.vc.home_time_eldrie_11","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"您竟然巡逻至如此深夜……您的用心，我深感佩服。","en":"Patrolling this late at night... I admire your strength of character.","ja":"このような深夜まで見廻りとは……そのお心がけ、感服いたしました"},"kind":"dialogue"},{"uid":"talk.vc.home_time_entokia_integrator_1#originalText","id":"talk.vc.home_time_entokia_integrator_1","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"哦？老师今天也这时候光临啊？你肚子肯定饿了，我们去吃饭吧。","en":"Oh, you're just now returning too? You must be hungry. Let's eat!","ja":"お、先生今日もこの時間ですか?腹減ってるでしょうメシ食いましょ、メシ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_entokia_integrator_4#originalText","id":"talk.vc.home_time_entokia_integrator_4","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"今天的天气也很棒呢。当索鲁斯大人心情好，镇民也显得愉快。","en":"Another lovely day! When Solus is in high spirits, so too are the townsfolk.","ja":"今日もいい天気ですなソルス様の機嫌がいいと街の人らも楽しそうですわ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_entokia_integrator_7#originalText","id":"talk.vc.home_time_entokia_integrator_7","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"老师，你的酒量很好吧？陪我一下嘛，男人之间百无禁忌地喝！","en":"Master, you can hold your liquor, can't you? Come drink with me! Just you and me, man to man!","ja":"先生、酒もいける口でしょう?少々付き合ってくださいよ男同士、無礼講で!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_entokia_integrator_10#originalText","id":"talk.vc.home_time_entokia_integrator_10","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"在这样的夜晚，磐拍那家伙是会哭的。牠很怕寂寞呢。","en":"It's nights like this that make Iwahaku howl the most. Such a needy dragon.","ja":"こんな夜は磐拍のヤツが泣くんですわ寂しがりなんですよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugene_1#originalText","id":"talk.vc.home_time_eugene_1","speaker":{"cn":"尤金","en":"Eugene","ja":"ユージーン"},"text":{"cn":"太阳都升那么高了，差不多出发吧。","en":"We should get going. The sun is way up.","ja":"日も高くなってきたしそろそろ行くか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugene_4#originalText","id":"talk.vc.home_time_eugene_4","speaker":{"cn":"尤金","en":"Eugene","ja":"ユージーン"},"text":{"cn":"你的便当是什么？……看起很好吃啊。","en":"What's in your lunch? That looks good.","ja":"お前の弁当はなんだ?……うまそうだな、それ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugene_7#originalText","id":"talk.vc.home_time_eugene_7","speaker":{"cn":"尤金","en":"Eugene","ja":"ユージーン"},"text":{"cn":"今天也是美好的一天。明天也多多指教啦。","en":"Today was another good day. See ya again tomorrow.","ja":"今日もいい一日だった明日もよろしく頼む"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugene_10#originalText","id":"talk.vc.home_time_eugene_10","speaker":{"cn":"尤金","en":"Eugene","ja":"ユージーン"},"text":{"cn":"夜袭吗？如果只是趁熟睡时袭击，可摘不下我的脑袋喔。","en":"Attack under cover of night? I'm not stupid enough to get my head cut off while I'm in bed.","ja":"夜襲か?寝込みを襲う程度では俺の首は取れんぞ?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_1#originalText","id":"talk.vc.home_time_eugeo_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"好了，快起床。都到吃早餐的时间了。","en":"Come on, wake up. It's already time for breakfast.","ja":"ほら、起きろよもう朝食の時間だ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_2#originalText","id":"talk.vc.home_time_eugeo_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我要去晨练空挥，你要一起去吗？","en":"I'm going out for some morning practice swings. Want to come with me?","ja":"僕は朝の素振りに行ってくるけど一緒に来るかい? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_3#originalText","id":"talk.vc.home_time_eugeo_3","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我可是有叫你了喔，你再睡下去不关我的事。","en":"Well, I woke you up. Don't say I didn't try.","ja":"僕は起こしたからねこれ以上は知らないよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_4#originalText","id":"talk.vc.home_time_eugeo_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"此时此刻，我原本应该是在挥斧伐木的……感觉真不可思议。","en":"Ordinarily, I'd be swinging my axe right now... This feels really surreal.","ja":"本当なら、今頃斧を振るってるはずなのに……なんか不思議な気持ちだよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_5#originalText","id":"talk.vc.home_time_eugeo_5","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"肚子也差不多饿了，我们来吃午餐吧。","en":"I'm getting hungry. Let's have some lunch.","ja":"そろそろお腹すいたねお昼ご飯にしようか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_6#originalText","id":"talk.vc.home_time_eugeo_6","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"午休已经结束了喔，快点回教室吧。","en":"Lunch break is over. We'd better get back to class.","ja":"もう昼休憩は終わりだよ急いで教室に戻ろう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_7#originalText","id":"talk.vc.home_time_eugeo_7","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"今天也很累人呢……你今天都做了什么事呢？","en":"I'm really tired again today. How about you? How was your day?","ja":"今日も疲れたね……そっちは、今日どんなことをしたんだい? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_8#originalText","id":"talk.vc.home_time_eugeo_8","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"剑必须要好好保养才行。还必须让天命回复。","en":"We need to take care of our swords, otherwise they lose endurance.","ja":"剣はちゃんと手入れしないとね天命も回復させないといけないし"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_9#originalText","id":"talk.vc.home_time_eugeo_9","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"晚上我们两个像这样在一起，也已经变成很理所当然的事情了呢。","en":"Spending time together at night like this feels so natural now.","ja":"夜、こうしてふたりでいるのももう当たり前になっちゃったね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_10#originalText","id":"talk.vc.home_time_eugeo_10","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"大半夜的怎么了吗？我说，你不会是想溜出房间吧？","en":"What's wrong? It's the middle of the night... You're not sneaking out, are you?","ja":"どうしたんだい、こんな夜中にまさか、部屋を抜け出す気じゃないだろうね? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_11#originalText","id":"talk.vc.home_time_eugeo_11","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"我有点睡不着……所以稍微活动一下筋骨。","en":"I couldn't sleep, so I thought I'd exercise a little.","ja":"ちょっと眠れないから……少し体を動かしてる"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_12#originalText","id":"talk.vc.home_time_eugeo_12","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"即便是同一片星空，看起来就是跟在卢利特看到的不一样。这是为什么呢……","en":"I could see the same stars back in Rulid, but they look different here somehow. I wonder why that is?","ja":"同じ星空でも、ルーリッドで見る星空とは違って見えるよどうしてだろう……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_child_1#originalText","id":"talk.vc.home_time_eugeo_child_1","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"早安，该起床啰？","en":"Good morning. It's already past time to wake up.","ja":"おはようもう起きる時間だよ? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_child_2#originalText","id":"talk.vc.home_time_eugeo_child_2","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"必须好好吃早餐才行呢。","en":"Breakfast is the most important meal of the day.","ja":"朝ごはんはしっかり食べないとね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_child_4#originalText","id":"talk.vc.home_time_eugeo_child_4","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"喂喂，现在吃午餐还太早了吧？","en":"Whoa, there! Isn't it a little early for lunch?","ja":"おいおい、まだお昼にはちょっと早いんじゃないか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_child_5#originalText","id":"talk.vc.home_time_eugeo_child_5","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"今天天气真好……这种日子，就会想去远一点的地方走走呢。","en":"What a nice day... Days like this make me want to go exploring further than I ever have before!","ja":"今日はいい天気だな……こんな日は、ちょっと遠くまで行ってみたくなるね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_child_7#originalText","id":"talk.vc.home_time_eugeo_child_7","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"今天就做到这里吧。要是太勉强，明天会吃不消的。","en":"Let's call it a day here. We don't want to be sore tomorrow.","ja":"今日はこの辺で終わりにしようか無理は明日に響くから"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_child_8#originalText","id":"talk.vc.home_time_eugeo_child_8","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"如果你方便的话，晚餐也跟我一起吃吧。","en":"We can have dinner together too, if you want.","ja":"晩御飯も、よかったら一緒に食べよう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_child_10#originalText","id":"talk.vc.home_time_eugeo_child_10","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"你还醒着吗？这样明天会起不来喔。","en":"Are you still awake? You'll be really tired tomorrow, you know?","ja":"まだ起きてたのかい? 明日起きられなくなるよ? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_child_11#originalText","id":"talk.vc.home_time_eugeo_child_11","speaker":{"cn":"尤吉欧","en":"Eugeo","ja":"ユージオ"},"text":{"cn":"夜晚会让人不禁去想很多事呢。真是不可思议。","en":"It's really easy for your mind to wander at night. Funny how that works, huh?","ja":"夜は、いろんなことを考えちゃうよねなんか不思議だな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_integrator_2#originalText","id":"talk.vc.home_time_eugeo_integrator_2","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_integrator_3#originalText","id":"talk.vc.home_time_eugeo_integrator_3","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_integrator_5#originalText","id":"talk.vc.home_time_eugeo_integrator_5","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_integrator_6#originalText","id":"talk.vc.home_time_eugeo_integrator_6","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_integrator_8#originalText","id":"talk.vc.home_time_eugeo_integrator_8","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_integrator_9#originalText","id":"talk.vc.home_time_eugeo_integrator_9","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_integrator_11#originalText","id":"talk.vc.home_time_eugeo_integrator_11","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_time_eugeo_integrator_12#originalText","id":"talk.vc.home_time_eugeo_integrator_12","speaker":{"cn":"集成骑士尤吉欧","en":"Integrity Knight Eugeo","ja":"整合騎士ユージオ"},"text":{"cn":"欠番","en":"欠番","ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_time_fanatio_1#originalText","id":"talk.vc.home_time_fanatio_1","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"早安。来，请您起床！","en":"Good morning. Time to get up!","ja":"おはようございますさあ、起きてください!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_fanatio_2#originalText","id":"talk.vc.home_time_fanatio_2","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"今日的索鲁斯恩惠似乎也相当丰沛呢。","en":"Today, we will once again receive Solus' bountiful blessings.","ja":"今日もソルスの恵みは豊かなようですね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_fanatio_4#originalText","id":"talk.vc.home_time_fanatio_4","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"我必须去查看部下的状况，先暂时告辞了。","en":"If you will excuse me. I must check on my subordinates.","ja":"部下たちの様子を見てこなければならないので、少し失礼します"},"kind":"dialogue"},{"uid":"talk.vc.home_time_fanatio_5#originalText","id":"talk.vc.home_time_fanatio_5","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"餐点已准备在那处了。","en":"If you wish to eat, preparations have been made over there.","ja":"食事なら、あちらに準備ができておりますよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_fanatio_7#originalText","id":"talk.vc.home_time_fanatio_7","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"您还在喝酒吗？就算是集成骑士也请不要太勉强自己。","en":"Are you drinking again?  Although you're an Integrity Knight,  please don't over do it.","ja":"またお酒を飲まれているのですか？いくら整合騎士とはいえ無理はなさらないでくださいね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_fanatio_8#originalText","id":"talk.vc.home_time_fanatio_8","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"洗澡水已经备好了。您先请吧。","en":"The bath is ready. You may go first.","ja":"お風呂の準備ができましたお先にどうぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_fanatio_10#originalText","id":"talk.vc.home_time_fanatio_10","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"月光很美呢。我喜欢沉静的夜晚。","en":"The moonlight is very pretty indeed. I do love quiet nights.","ja":"月の明かりがきれいですね静かな夜は好きです"},"kind":"dialogue"},{"uid":"talk.vc.home_time_fanatio_11#originalText","id":"talk.vc.home_time_fanatio_11","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"明天请您别睡过头，要准时起床啊。","en":"Please get up early tomorrow. Don't oversleep.","ja":"明日は寝坊せずに起きてくださいね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_fizel_1#originalText","id":"talk.vc.home_time_fizel_1","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"早安。不知道今天会不会有什么开心的事呢。","en":"Good morning. Hope there's something fun to do today.","ja":"おはよう今日は楽しいことはあるかしら"},"kind":"dialogue"},{"uid":"talk.vc.home_time_fizel_2#originalText","id":"talk.vc.home_time_fizel_2","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"一想到从早上就要开始念书，心情就很沉重呢……","en":"It's always dreary getting up in the morning when you know there's nothing but studying to do.","ja":"朝からお勉強だと思うと気が重いのよね……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_fizel_4#originalText","id":"talk.vc.home_time_fizel_4","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"午餐？嗯，我要一起吃！","en":"Lunch? Sure, I'll eat with you!","ja":"お昼ご飯?うん、一緒に食べる!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_fizel_5#originalText","id":"talk.vc.home_time_fizel_5","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"你觉得，为什么吃完饭就会想睡觉呢？","en":"Why do you think we get sleepy right after we eat?","ja":"ご飯を食べると眠くなるのはどうしてだと思う?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_fizel_7#originalText","id":"talk.vc.home_time_fizel_7","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"唉～今天也好累喔。我不要学神圣术了啦～！","en":"Ahhh, another exhausting day. I'm just so sick of Sacred Arts!","ja":"はああ、今日も疲れたわもう神聖術の勉強はいやー!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_fizel_8#originalText","id":"talk.vc.home_time_fizel_8","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"我其实想要熬夜，但是会被骂。","en":"Truthfully, I would love to stay up late, but I don't like being yelled at.","ja":"本当は夜更かししたいんだけど怒られちゃうのよねえ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_fizel_10#originalText","id":"talk.vc.home_time_fizel_10","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"嗯嗯……已经早上了吗？","en":"Mmm...morning already?","ja":"んん……もう朝?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_fizel_11#originalText","id":"talk.vc.home_time_fizel_11","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"你睡不着吗？我也是。啊～啊～真希望涅尔就在我旁边。","en":"Can't sleep? Neither can I. Oh, I wish Linel were here.","ja":"眠れないの?あたしも一緒なのあーあ、ネルが隣にいればなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_frenica_1#originalText","id":"talk.vc.home_time_frenica_1","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"早安。今天也是个美好的早晨呢。","en":"Good morning! What a lovely morning it is.","ja":"おはよう今日もいい朝だね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_frenica_4#originalText","id":"talk.vc.home_time_frenica_4","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"你吃过午餐了吗？还没的话，我们一起吃吧？","en":"Did you have lunch yet? If not, wanna join me?","ja":"お昼は、もう食べた?まだだったら、一緒に食べよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_frenica_7#originalText","id":"talk.vc.home_time_frenica_7","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"已经这么晚了，开心的时光总是过得这么快呢。","en":"Look how late it's gotten. Time does fly when you're having fun.","ja":"もうこんな時間だ楽しいと、すぐ時間が過ぎちゃうね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_frenica_10#originalText","id":"talk.vc.home_time_frenica_10","speaker":{"cn":"芙蕾妮卡","en":"Frenica","ja":"フレニーカ"},"text":{"cn":"你睡不着吗？其实我也是。呵呵……真巧呢。","en":"You can't sleep? Neither can I. Hehe.","ja":"眠れないの?実は、私もなのふふ……奇遇だね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_geero_1#originalText","id":"talk.vc.home_time_geero_1","speaker":{"cn":"吉罗","en":"Geero","ja":"ジーロ"},"text":{"cn":"早安那个……如果您方便的话，等会可以指导我剑术吗","en":"Good morning. Um... If it’s not too much trouble, can you train with me later?","ja":"おはようございますあの……よければ、後ほど剣の指導を賜われないでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_geero_4#originalText","id":"talk.vc.home_time_geero_4","speaker":{"cn":"吉罗","en":"Geero","ja":"ジーロ"},"text":{"cn":"为了迎接总有一天会到来的那一刻不好好摄取营养不行呢","en":"You should come prepared and with a full stomach.","ja":"來るべき時に備えて食事もしっかり摂らねばいけませんね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_geero_7#originalText","id":"talk.vc.home_time_geero_7","speaker":{"cn":"吉罗","en":"Geero","ja":"ジーロ"},"text":{"cn":"夜晚的风真舒服","en":"The night breeze feels so nice.","ja":"夜風が気持ちいいですね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_geero_10#originalText","id":"talk.vc.home_time_geero_10","speaker":{"cn":"吉罗","en":"Geero","ja":"ジーロ"},"text":{"cn":"好好治愈身心为了明天做准备吧","en":"Have a good rest and we’ll get ready tomorrow.","ja":"心身を癒してまた明日に備えましょう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_golgorosso_1#originalText","id":"talk.vc.home_time_golgorosso_1","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"嗨，你醒啦？赶紧开始晨练吧！","en":"Oh, awake already? Let's get to our morning training!","ja":"おう、起きたかさっそく朝の鍛錬を始めるぞ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_golgorosso_4#originalText","id":"talk.vc.home_time_golgorosso_4","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"要好好吃饭啊！强健体魄要从饮食做起！","en":"Make sure you eat up! A strong body needs ample nourishment.","ja":"飯はしっかり食えよ!強い体はまず食事からだ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_golgorosso_7#originalText","id":"talk.vc.home_time_golgorosso_7","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"已经天黑啦……今天就到此为止吧。","en":"It's already gotten dark. Let's call it a day.","ja":"もう暗くなってしまったか……今日はここまでだな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_golgorosso_10#originalText","id":"talk.vc.home_time_golgorosso_10","speaker":{"cn":"哥鲁哥罗索","en":"Golgorosso","ja":"ゴルゴロッソ"},"text":{"cn":"你热衷练习是好事……但不要勉强练到半夜啊。","en":"I appreciate your dedication... But don't overwork yourself at night.","ja":"熱心なのはいいことだが……夜中まで無理はするなよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_heathcliff_1#originalText","id":"talk.vc.home_time_heathcliff_1","speaker":{"cn":"希兹克利夫","en":"Heathcliff","ja":"ヒースクリフ"},"text":{"cn":"早安，一早就看的到你的脸，看来今天会是美好的一天。","en":"Morning. Seeing your face this morning is a sign that today will be a lucky day.","ja":"おはよう朝から君の顔を見られるとは今日は運がいいようだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_heathcliff_4#originalText","id":"talk.vc.home_time_heathcliff_4","speaker":{"cn":"希兹克利夫","en":"Heathcliff","ja":"ヒースクリフ"},"text":{"cn":"白天总是很忙啊。公会的经营看起来好像很简单，但并不轻松啊。","en":"Your evenings look somewhat busy. Even the guild doesn’t seem so relaxed.","ja":"昼間は、どうにも忙しくてねギルドの運営も、こう見えて楽ではないんだよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_heathcliff_7#originalText","id":"talk.vc.home_time_heathcliff_7","speaker":{"cn":"希兹克利夫","en":"Heathcliff","ja":"ヒースクリフ"},"text":{"cn":"这么晚了还跟我混在一起好吗？你爱的人还在等着你吧？","en":"I wonder if it's ok for me to stay out this late? Don't you have a lovely person waiting for you?","ja":"こんな夜遅くに、私なんかといていいのか?愛しい人が待っているんだろう?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_heathcliff_10#originalText","id":"talk.vc.home_time_heathcliff_10","speaker":{"cn":"希兹克利夫","en":"Heathcliff","ja":"ヒースクリフ"},"text":{"cn":"大半夜的有什么事吗？还是说，你是来偷袭的呢？","en":"What is the purpose of midnight? I wonder if it's for foul play.","ja":"こんな夜中になんの用だ?それとも、闇討ちに来たのかな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_hoveren_1#originalText","id":"talk.vc.home_time_hoveren_1","speaker":{"cn":"何布雷恩","en":"Hoveren","ja":"ホーブレン"},"text":{"cn":"早安！有好好休息吗？","en":"Good morning! Did you have have a good rest?","ja":"おはようございます!ゆっくり休めましたか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_hoveren_4#originalText","id":"talk.vc.home_time_hoveren_4","speaker":{"cn":"何布雷恩","en":"Hoveren","ja":"ホーブレン"},"text":{"cn":"我今天也会好好完成下午的任务！","en":"Ready for afternoon duties!","ja":"午後の任務もしっかりと勤めあげて参ります!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_hoveren_7#originalText","id":"talk.vc.home_time_hoveren_7","speaker":{"cn":"何布雷恩","en":"Hoveren","ja":"ホーブレン"},"text":{"cn":"我再去做一下神圣术的训练","en":"I’m going to work on my Sacred Arts skills just a little more.","ja":"もう少しだけ神聖術の訓練をして参ります"},"kind":"dialogue"},{"uid":"talk.vc.home_time_hoveren_10#originalText","id":"talk.vc.home_time_hoveren_10","speaker":{"cn":"何布雷恩","en":"Hoveren","ja":"ホーブレン"},"text":{"cn":"巡逻就交给我们吧您请好好休息","en":"Leave patrolling to us. Please get some rest.","ja":"見廻りは我らに任せてゆっくりお休みになってください"},"kind":"dialogue"},{"uid":"talk.vc.home_time_humbert_1#originalText","id":"talk.vc.home_time_humbert_1","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"该死，还是想睡……索鲁斯太刺眼了吧。","en":"Damn it, I'm still sleepy... Solus’s rays are burning my eyes.","ja":"くそ、まだ眠いな……ソルスが目に痛いぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_humbert_4#originalText","id":"talk.vc.home_time_humbert_4","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"那群乡下剑士，吃的东西想必很寒酸吧。","en":"That pair of country bumpkins are sure eating a meager lunch.","ja":"あの田舎剣士どもはさぞ寂しいものを食っているのであろうな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_humbert_7#originalText","id":"talk.vc.home_time_humbert_7","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"那么，今天也要跟那个随侍……","en":"I think I'll call upon my page again tonight...","ja":"さて、今日もまたあの傍付きに……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_humbert_10#originalText","id":"talk.vc.home_time_humbert_10","speaker":{"cn":"温贝尔","en":"Humbert","ja":"ウンベール"},"text":{"cn":"夜晚才正要开始。还有很多乐趣……","en":"The night is young. The fun is yet to come.","ja":"夜はこれからだまだまだお楽しみが……クックック"},"kind":"dialogue"},{"uid":"talk.vc.home_time_iskahn_1#originalText","id":"talk.vc.home_time_iskahn_1","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"喔，你真迟。我早上的训练都已经做完了。","en":"Oi, you're pretty late. Morning practice just wrapped up.","ja":"おう、遅かったなこっちはもう朝の訓練を終えてきたところだぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_iskahn_2#originalText","id":"talk.vc.home_time_iskahn_2","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"早上就吃多一点吧。不吃饱一点，身体也提供不了能量。","en":"Make sure you're eating properly in the morning. You won't be able to build up your body if you don't.","ja":"朝はしっかり食えよ食わねえと、体が造れないからな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_iskahn_4#originalText","id":"talk.vc.home_time_iskahn_4","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"今天有新的斗士进来。要趁他们还年轻的时候好好锻炼，培养成强壮的战士。","en":"A new warrior will be joining us today. This brat has been training hard since he was young to be a strong warrior.","ja":"今日は新入りの闘士が入るんだガキの内からみっちり鍛えて強い戦士に育てるんだよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_iskahn_5#originalText","id":"talk.vc.home_time_iskahn_5","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"喂，别因为这种程度就筋疲力尽！从头再来一次！","en":"Oi, don't get tired on me! Give it another shot, starting from the head!","ja":"おい、その程度でへばってんじゃねえ!もう一回、頭からやり直しだ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_iskahn_7#originalText","id":"talk.vc.home_time_iskahn_7","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"我对领土之类的没兴趣。我只是想变强。那是我们的愿望，我们的生存方式。","en":"I can care less about territory. I just want to get stronger, simple as that. That is our wish and our way of life.","ja":"領土になんか興味はねえただ、強くなる。それだけが俺たちの望みであり、生き方だ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_iskahn_8#originalText","id":"talk.vc.home_time_iskahn_8","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"就只有菜鸟才会说「累到什么都不想吃」。就算有多累，也一定要吃饭。","en":"Being too tired to eat is what novices say. No matter how tired you get, you have to make sure to eat.","ja":"疲れて何も食えねえ、なんてのは見習いの言うことだ。どんなにへばってても、メシは食わねえとな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_iskahn_10#originalText","id":"talk.vc.home_time_iskahn_10","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"真亏你这种时间还能醒着。怪不得你总是看起来很困。","en":"Are you always up this late? No wonder you always look tired.","ja":"よくこんな時間まで起きていられるな?だからいつも眠そうなんだぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_iskahn_11#originalText","id":"talk.vc.home_time_iskahn_11","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"你很啰唆耶。晚上就睡觉吧，真是的……","en":"Oh, shut up. The night is for sleeping...","ja":"うるせえなあ夜は寝ろよ、まったく……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_jace_1#originalText","id":"talk.vc.home_time_jace_1","speaker":{"cn":"杰伊斯","en":"Jayce","ja":"ジェイス"},"text":{"cn":"早安！今天也麻烦你教导我了！","en":"Good morning! I look forward to training with you today!","ja":"おはようございます!本日もご指導のほどよろしくお願いいたします!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_jace_4#originalText","id":"talk.vc.home_time_jace_4","speaker":{"cn":"杰伊斯","en":"Jayce","ja":"ジェイス"},"text":{"cn":"在肚子饿到动不了前先开动吧！","en":"Let’s grab a bite before we’re too hungry to move!","ja":"お腹が減りすぎて動けなくなる前にいただきましょう!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_jace_7#originalText","id":"talk.vc.home_time_jace_7","speaker":{"cn":"杰伊斯","en":"Jayce","ja":"ジェイス"},"text":{"cn":"今天一整天辛苦了！要帮您拿食物过来吗？","en":"Great work today! Should we get something to eat?","ja":"本日も1日お疲れ様でした!食事をお持ちいたしましょうか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_jace_10#originalText","id":"talk.vc.home_time_jace_10","speaker":{"cn":"杰伊斯","en":"Jayce","ja":"ジェイス"},"text":{"cn":"是……非常抱歉不小心醒来了……我马上回去自己的房间","en":"My... My apologizes! It was a mistake... I’ll return to my own room now!","ja":"はっ……申し訳ありません!目が醒めてしまいまして……すぐに自室へ戻ります!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kagemune_1#originalText","id":"talk.vc.home_time_kagemune_1","speaker":{"cn":"影宗","en":"Kagemune","ja":"カゲムネ"},"text":{"cn":"早安。今天似乎是好天气呢。","en":"Good morning. The weather looks nice.","ja":"おはよう今日はいい天気みたいだな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kagemune_4#originalText","id":"talk.vc.home_time_kagemune_4","speaker":{"cn":"影宗","en":"Kagemune","ja":"カゲムネ"},"text":{"cn":"要不要一起吃午餐？","en":"Wanna eat lunch with me?","ja":"昼飯なら一緒に食うか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kagemune_7#originalText","id":"talk.vc.home_time_kagemune_7","speaker":{"cn":"影宗","en":"Kagemune","ja":"カゲムネ"},"text":{"cn":"要跟强敌对战的话，我挺推荐挑晚上进行喔。","en":"You wouldn't think it, but nights are ideal for fighting against strong opponents.","ja":"強い奴とやるなら夜はわりとおすすめだぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kagemune_10#originalText","id":"talk.vc.home_time_kagemune_10","speaker":{"cn":"影宗","en":"Kagemune","ja":"カゲムネ"},"text":{"cn":"实在是很困，差不多该睡了。","en":"Okay, even I'm sleepy now. Let's turn in.","ja":"さすがに眠いなそろそろ寝よう"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kibaou_1#originalText","id":"talk.vc.home_time_kibaou_1","speaker":{"cn":"牙王","en":"Kibaou","ja":"キバオウ"},"text":{"cn":"嘿，你现在才醒？太阳都晒屁股了。","en":"Oh. So, you finally decided to wake up? The sun rose hours ago.","ja":"おう、今頃起きたんかとっくにお天道さん昇っとるで"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kibaou_4#originalText","id":"talk.vc.home_time_kibaou_4","speaker":{"cn":"牙王","en":"Kibaou","ja":"キバオウ"},"text":{"cn":"只是吃顿饭的话，我倒是可以跟你一起吃啦。","en":"Well, I don't mind eating with ya.","ja":"まあ飯ぐらいなら一緒に食ってやってもええけどな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kibaou_7#originalText","id":"talk.vc.home_time_kibaou_7","speaker":{"cn":"牙王","en":"Kibaou","ja":"キバオウ"},"text":{"cn":"我要休息了。你也别再打混了，去躺平如何？","en":"I'm gonna take a nap. You should stop farting around and do the same.","ja":"わいはもう休むでダラダラせんとお前も寝たらどうや"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kibaou_10#originalText","id":"talk.vc.home_time_kibaou_10","speaker":{"cn":"牙王","en":"Kibaou","ja":"キバオウ"},"text":{"cn":"我可不是睡不着，我这是在保持警戒！","en":"I'm not having trouble sleeping. I was standing guard!","ja":"別に寝つけんわけやないで警戒しとったんや!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_1#originalText","id":"talk.vc.home_time_kirito_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"嗯～再睡一下吧……","en":"Mmm...sleepy...","ja":"んー、まだ寝ようぜ……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_2#originalText","id":"talk.vc.home_time_kirito_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"啊，你的头发翘起来了。要我帮你弄平吗？","en":"Man, you have some serious bed head. Want me to fix it?","ja":"あ、寝癖ついてるぞなおしていいか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_3#originalText","id":"talk.vc.home_time_kirito_3","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"好～今天也要努力加油喔！","en":"Okay! Let's put in another day's work!","ja":"さーて、今日も1日張り切っていこう!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_4#originalText","id":"talk.vc.home_time_kirito_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"你吃过午餐了吗？还没的话就一起吃吧。","en":"Did you have lunch yet? If not, wanna join me?","ja":"昼ごはんもう食べたか?まだなら一緒に食べようぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_5#originalText","id":"talk.vc.home_time_kirito_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"今天天气真好。在这种日子进行训练，真是太浪费了……","en":"The weather is so nice today. Too bad we have to spend the day training.","ja":"今日は最高の気象だなこんな日に稽古するなんてもったいない……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_6#originalText","id":"talk.vc.home_time_kirito_6","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"午、午餐吃太多了……","en":"Ugh... I ate too much lunch.","ja":"ひ、昼飯食べすぎた……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_7#originalText","id":"talk.vc.home_time_kirito_7","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"今天也辛苦你了。泡个澡好好放松一下吧。","en":"Good work today! Let's take a nice, long bath.","ja":"今日も1日お疲れさま風呂入ってゆっくりしようぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_8#originalText","id":"talk.vc.home_time_kirito_8","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"天黑了呢。要不要出去散步看个夜景？","en":"It's getting pretty dark. Want to go on a little night walk?","ja":"だいぶ暗くなってきたな少し夜道を散歩でもどうだ?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_9#originalText","id":"talk.vc.home_time_kirito_9","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"好啦～接下来做什么呢？现在睡觉还早嘛。","en":"It's still a bit too early to go to sleep. Wanna do something?","ja":"さーて何をしようか?まだ寝るには早いだろ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_10#originalText","id":"talk.vc.home_time_kirito_10","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"睡不着吗？那我们就再多说一下话吧。","en":"Can't sleep? Wanna talk some more, then?","ja":"寝れないのか?じゃあもう少し、話そうぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_11#originalText","id":"talk.vc.home_time_kirito_11","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"那么，明天早上八点叫我起床。晚安啰。","en":"Wake me up at eight,  tomorrow, okay? Goodnight.","ja":"そんじゃ、明日は8時に起こしてくれおやすみ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_12#originalText","id":"talk.vc.home_time_kirito_12","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"睡不着的话，要不要一起去外面？我现在很想看星星呢。","en":"If you can't sleep, wanna go outside with me? I'm in the mood for some stargazing.","ja":"寝れないなら一緒に外行かないか?星が見たい気分なんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_child_1#originalText","id":"talk.vc.home_time_kirito_child_1","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"呼哇……再睡一下啦。","en":"Ahhh... I think I'll go back to sleep.","ja":"ふわあ……まだ寝てようよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_child_2#originalText","id":"talk.vc.home_time_kirito_child_2","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"好吧，我差不多该起来了。不然就要被骂啦。","en":"Oh well. Guess I'd better get up. Don't wanna get yelled at.","ja":"しょうがない、そろそろ起きるか怒られちゃうもんな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_child_4#originalText","id":"talk.vc.home_time_kirito_child_4","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"差不多该吃饭了呢。今天吃什么呢～","en":"It's almost dinnertime. I wonder what's on the menu tonight?","ja":"そろそろ飯の時間だよな今日の食事は何かなー"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_child_5#originalText","id":"talk.vc.home_time_kirito_child_5","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"既然今天这么温暖，就来睡个午觉吧！","en":"The weather is nice and warm. Time for a nap!","ja":"さて、今日は暖かいし昼寝でもしようぜ! "},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_child_7#originalText","id":"talk.vc.home_time_kirito_child_7","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"呼～肚子好饿喔。晚餐还没好吗～","en":"Boy, am I hungry! Is it dinnertime yet?","ja":"ふー、腹ペコだよ晩御飯はまだかなー"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_child_8#originalText","id":"talk.vc.home_time_kirito_child_8","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"咦～还不用睡吧？我不困耶。","en":"Aw, can't I stay up? I'm not sleepy yet.","ja":"えー、まだ起きててもいいだろ? 眠くないんだよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_child_10#originalText","id":"talk.vc.home_time_kirito_child_10","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"嗯……怎么了？作恶梦了吗？","en":"What's wrong? Bad dream?","ja":"ん……どうした? 怖い夢でも見たのか? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_kirito_child_11#originalText","id":"talk.vc.home_time_kirito_child_11","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"你也醒啦。那我们要不要稍微出门逛逛？","en":"Did you wake up, too? Wanna go outside then?","ja":"お前も目が覚めたのかじゃあ、ちょっと外に出てみないか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_klein_1#originalText","id":"talk.vc.home_time_klein_1","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"唷，起来啦？那我们出发吧！","en":"Oh, you're up. Well, let's head out!","ja":"おう、起きたか!それじゃ、出発しようぜ!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_klein_2#originalText","id":"talk.vc.home_time_klein_2","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"呼啊啊……今天没睡饱呢。","en":"Ahhh... I'm gonna feel like a zombie all day.","ja":"ふああ……今日は眠気が取れねぇなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_klein_4#originalText","id":"talk.vc.home_time_klein_4","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"嚼嚼……吃东西的感觉也很真实耶。","en":"Munch, munch... Wow, even eating feels real!","ja":"もぐもぐ……食ってる感覚もずいぶんリアルなんだな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_klein_5#originalText","id":"talk.vc.home_time_klein_5","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"还睡午觉喔？你真的很爱睡耶。","en":"Napping again? Wow, you really do love sleeping.","ja":"また昼寝かよほんと寝るのが好きだな、お前は"},"kind":"dialogue"},{"uid":"talk.vc.home_time_klein_7#originalText","id":"talk.vc.home_time_klein_7","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"辛苦啦！我们今天都有好好努力呢！","en":"Good work, trooper! I think we both deserve a medal today.","ja":"おつかれさん!今日もお互い、頑張ったな!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_klein_8#originalText","id":"talk.vc.home_time_klein_8","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"你晚上要去散步吗？好啊，我陪你。","en":"A night walk? Cool, I'm coming with!","ja":"夜の散歩か?いいぜ、付き合うよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_klein_10#originalText","id":"talk.vc.home_time_klein_10","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"管你怎么说，三更半夜了就乖乖去睡觉。","en":"Dude, stop it. It's late! Just go to sleep.","ja":"なんだってんだ、こんな夜中に大人しくベッドに入っとけ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_klein_11#originalText","id":"talk.vc.home_time_klein_11","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"睡不着的话，就去稍微活动一下筋骨吧。","en":"If you can't sleep, a little exercise sometimes does the trick.","ja":"眠れないなら、少し体を動かすといいぜ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kuradeel_1#originalText","id":"talk.vc.home_time_kuradeel_1","speaker":{"cn":"克拉帝尔","en":"Kuradeel","ja":"クラディール"},"text":{"cn":"早安！请吩咐今日的预定吧！","en":"Good morning! I eagerly await my itinerary!","ja":"おはようございます!それでは、本日の予定をお申し付けください!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kuradeel_4#originalText","id":"talk.vc.home_time_kuradeel_4","speaker":{"cn":"克拉帝尔","en":"Kuradeel","ja":"クラディール"},"text":{"cn":"午餐准备好了。来来，往这走。","en":"I have prepared your lunch. Come, this way.","ja":"食事を用意しておきましたささ、こちらへ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kuradeel_7#originalText","id":"talk.vc.home_time_kuradeel_7","speaker":{"cn":"克拉帝尔","en":"Kuradeel","ja":"クラディール"},"text":{"cn":"晚上是危险时段……我克拉帝尔，会随时待命在你的身旁。","en":"Nights are dangerous. You can count on me to protect you!","ja":"夜は危険な時間……このクラディール、いつでもお側に控えております"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kuradeel_10#originalText","id":"talk.vc.home_time_kuradeel_10","speaker":{"cn":"克拉帝尔","en":"Kuradeel","ja":"クラディール"},"text":{"cn":"喔喔，你居然会在这个时间来看我……","en":"Wow! I'm honored that you would come to see me so late...","ja":"おお、このような時間に会いに来てくださるとは……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kureha_1#originalText","id":"talk.vc.home_time_kureha_1","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"早安。今天要去打哪个任务呢？","en":"Morning. What kind of quest will we be going to today?","ja":"おはよう今日は、どんなクエストに行くの?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kureha_2#originalText","id":"talk.vc.home_time_kureha_2","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"呵呵……你每天早上看起来都很困呢。","en":"Hehe... You always seem sleepy in the morning.","ja":"ふふ……あなたは、いつも朝は眠そうね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kureha_4#originalText","id":"talk.vc.home_time_kureha_4","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"又在睡午觉……？天气很好的时候，你是不是一直都在睡啊？","en":"Napping again...? Do you always sleep when the weather is nice?","ja":"またお昼寝……?天気がいい日は、いつも寝てない?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kureha_5#originalText","id":"talk.vc.home_time_kureha_5","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"你来的正好。有时间的话，我们一起去吃午饭吧？","en":"It's about that time of the day. How about joining us for some lunch?","ja":"ちょうどよかった時間があるなら、あたしたちとお昼、一緒に食べない?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kureha_7#originalText","id":"talk.vc.home_time_kureha_7","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"今天的成果如何？我们这边好像还好。","en":"How are today's results looking? We're a little on the so and so side of things.","ja":"今日の成果はどんな感じ?あたしたちの方は、まあまあって感じかな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kureha_8#originalText","id":"talk.vc.home_time_kureha_8","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"今天要不要大家一起开个派对啊？我去邀大家！","en":"How about we do a party with everyone today? I'll go and invite everyone!","ja":"今日はみんなでパーティーしない?あたし、みんなに声かけるから!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kureha_10#originalText","id":"talk.vc.home_time_kureha_10","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"……不小心被你看到奇怪的地方了。偶尔会有晚上睡不着的时候。","en":"...Looks like you caught me at a weird place. Sometimes, even at night I can't sleep.","ja":"……変なところ見られちゃったなたまにね、夜になっても眠れないことがあるの"},"kind":"dialogue"},{"uid":"talk.vc.home_time_kureha_11#originalText","id":"talk.vc.home_time_kureha_11","speaker":{"cn":"红叶","en":"Kureha","ja":"クレハ"},"text":{"cn":"都这时间了还没睡吗？不过，我也一样就是了……我们彼此还是都尽量早点睡吧。","en":"You're awake at this hour? I'm also the same... but we should both probably head off to bed early.","ja":"こんな時間まで起きてるの?まあ、あたしも同じだけど……なるべく早く寝ようね、お互い"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_1#originalText","id":"talk.vc.home_time_leafa_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"早安！真是舒爽的早晨呢～要不要一起晨练？","en":"Good morning! And what a lovely morning it is. Wanna do some training?","ja":"おはよう! 気持ちのいい朝だよー一緒に朝練する? "},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_2#originalText","id":"talk.vc.home_time_leafa_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"啊哈哈，你的头发太好笑了吧！过来一下，我帮你整理整理。","en":"Hahaha! Whoa, look at that cow lick! Come here, I'll fix it.","ja":"あはは、頭すごいよ! ちょっとこっちきて整えてあげるから"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_3#originalText","id":"talk.vc.home_time_leafa_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"我人是起来了，但还是很困……感觉又会睡着……","en":"I may be awake, but I'm still sleepy... I just might fall asleep again...","ja":"起きたのはいいけどまだ眠いなあ……二度寝しちゃいそう……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_4#originalText","id":"talk.vc.home_time_leafa_4","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"我今天中午以后就没有安排了。所以，我们出去玩吧。","en":"I have no plans this afternoon, so let's go out somewhere!","ja":"今日は午後から予定ないんだだから、どこかに遊びに行こうよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_5#originalText","id":"talk.vc.home_time_leafa_5","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"中午一起吃饭吧。妈妈做的便当有两份呢！","en":"Wanna have lunch together? Mom made enough for both of us!","ja":"お昼、一緒に食べよ? お母さんのお弁当ふたり分あるから! "},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_6#originalText","id":"talk.vc.home_time_leafa_6","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"啊，在睡午觉……好～我也一起睡吧！","en":"Oh! Look who's taking a nap... Fine! Two can play at that game.","ja":"あ、お昼寝してる……よーし、あたしも寝ちゃおう! "},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_7#originalText","id":"talk.vc.home_time_leafa_7","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"今天一整天都在训练，真是累死我了……累到我想直接睡觉了。","en":"I spent the whole day training, and I'm exhausted. I could fall asleep standing up!","ja":"今日、一日中稽古だったからもうクタクタ……このまま寝ちゃいたいくらい"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_8#originalText","id":"talk.vc.home_time_leafa_8","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"呼～洗了澡后全身清爽！","en":"Ahhh, nothing is more refreshing than a good bath!","ja":"はあー、お風呂でさっぱりした! "},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_9#originalText","id":"talk.vc.home_time_leafa_9","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"晚上就是要保养竹刀。这是很重要的道具，所以得好好保养才行。","en":"I'll be polishing my bamboo sword tonight. I have to give it some love, since it's so special to me.","ja":"夜は、竹刀の手入れをするの大切な道具だから、ちゃんと磨いてあげないと"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_10#originalText","id":"talk.vc.home_time_leafa_10","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"在半夜醒过来，就会让我有点不安。所以我才来看看你的。","en":"I always feel anxious when I wake up in the middle of the night. That's why I always come to see you...","ja":"夜中目が覚めるとちょっと不安になるんだだから、こうやって顔を見に来るの"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_11#originalText","id":"talk.vc.home_time_leafa_11","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"再不去睡的话，明天早上会很痛苦的。那么，晚安了。","en":"We'd better go to sleep soon, or tomorrow's gonna suck. Well, goodnight.","ja":"そろそろ寝ないと、明日の朝がきついんだそれじゃ、おやすみなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_12#originalText","id":"talk.vc.home_time_leafa_12","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"抱歉，吵醒你了吗？因为我有点想看你的睡脸……对不起喔。","en":"Sorry, did I wake you? Sorry, I was just watching you sleep, that's all.","ja":"ごめん、起こしちゃった? ちょっと、寝顔を見てたかったから……ごめんね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_linel_1#originalText","id":"talk.vc.home_time_linel_1","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"早、早安。你起得好早呢。","en":"Good morning. You're sure up early.","ja":"お、おはようございます朝は早いんですね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_linel_2#originalText","id":"talk.vc.home_time_linel_2","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"早上要绑头发。你下次可以帮我吗？","en":"I braid my hair every morning. Will you braid my hair for me?","ja":"朝は髪を編むんです今度やってくれますか?"},"kind":"dialogue"}]};
